findings.codeql_raw_query:
/**
 * @name attrs: trace dynamic code execution sources
 * @description Trace whether untrusted/remote data can reach eval/exec/compile in attr/_make.py
 * @kind path-problem
 * @problem.severity error
 * @id py/attrs/dynamic-code-execution-path
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module DynExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      ce.getLocation().getFile().getRelativePath() = "src/attr/_make.py" and
      sink = ce.getCode()
    )
  }
}

module DynExecFlow = TaintTracking::Global<DynExecConfig>;
import DynExecFlow::PathGraph

from DynExecFlow::PathNode source, DynExecFlow::PathNode sink
where DynExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches dynamic code execution in attrs $@.", source.getNode(), "user input"
